def target(key,table,model,row,quantity,printed,p,where,se=None,stars='none printed',claims=None,direction='none',tier=None):
    s=printed.replace('−','-').replace(',','').replace('%','') if printed is not None else None
    t={'target_id':f'T{len(targets)+1}','table_or_figure':table,'model_label':model,'row_label':row,
       'quantity':quantity,'value_as_printed':printed,'value':float(s) if s is not None else None,
       'decimals_printed':len(s.split('.')[1]) if s and '.' in s else (0 if s is not None else None),
       'published_se':float(se) if se is not None else None,
       'se_type_as_described':'Standard errors in parentheses; covariance estimator and SE transformation not stated' if se is not None else 'not stated',
       'exact_p':None,'stars_or_inequality':stars,'alpha_convention':KEY if table in ['Table 1','Table 5','Table 6'] else None,
       'tail':'not stated','hypothesized_direction':direction,'N':None,'claim_ids':claims or [],'source':src(p,where)}
    if tier: t['tier']=tier
    targets.append(t); refs[key]=t['target_id']; return t

