steps=[]
def step(rule,cols,p,w,certainty): steps.append({'step':len(steps)+1,'rule':rule,'variables_used':cols,'source':src(p,w),'certainty':certainty})
step('Load the S1 season files for seasons 2000 through 2005 inclusive. Keep season_type == REG; use season, not calendar year. For game summaries use the S2 regular-season game universe for the same seasons. Audit unavailable game coverage without fabricating play rows. Source mapping: data_description/source_descriptions.md, S1–S2.', ['S1.season','S1.season_type','S2.season','S2.game_type'],8,'Data; Endnote 1 on PDF p. 15','explicit')
step('Verify S1 keys game_id + play_id and S2 game_id uniqueness; merge S2 many-to-one by game_id. Resolve conflicting duplicate keys as a source-quality question rather than arbitrary deletion. Normalize team identities LA→STL, LAC→SD, LV→OAK for comparison with S2, retaining stable franchise identities for team effects. Source mapping: data_description/data_dictionary.md, Linkage.', ['S1.game_id','S1.play_id','S1.posteam','S1.defteam','S2.game_id','S2.home_team','S2.away_team'],9,'Data Analysis Model / team effects; source linkage is reader implementation inference','inferred')
step('Retain regulation qtr in {1,2,3,4}; exclude all overtime. Do not exclude regulation plays merely because their game later enters overtime.', ['S1.qtr','S1.game_half'],15,'Endnote 2','explicit')
step('Start from down == 4. Remove administrative events (timeouts and period-end markers), kickoff/extra-point/two-point events, and deleted plays when documented by the source. Closest executable convention: retain actual pass/run/punt/field-goal plays with a known offensive team; distinguish an executed play with a penalty from an administrative no_play row. Classification of nullified plays, kneels, spikes, fakes, aborted kicks, and intentional safeties is not specified; flag them for a prespecified adjudication rule, leaving unknown decisions missing. Do not define the outcome from conversion success alone or silently classify every non-kick row as an attempt.', ['S1.down','S1.play_type','S1.posteam','S1.timeout','S1.quarter_end','S1.play_deleted','S1.penalty','S1.desc','S1.qb_kneel','S1.qb_spike','S1.aborted_play','S1.punt_attempt','S1.field_goal_attempt'],8,'Data; Risk Taking; appendix on PDF p. 15','unclear')
step('Remove plays with regulation game_seconds_remaining <= 120. This implements removal of the last two minutes; the exact treatment of a snap at 02:00 is not explicit. Keep the end of the first half. Prefer the pre-play clock, and flag disagreements with (4-qtr)*900 + quarter_seconds_remaining.', ['S1.game_seconds_remaining','S1.qtr','S1.quarter_seconds_remaining','S1.time'],16,'Endnote 3 (begins PDF p. 15)','inferred')
step('Construct all variables below from the pre-play state. Obtain a documented season-specific conference-membership lookup before deriving same_conference. S2.div_game supplies same_division. Do not replace either explicit control with a proxy, omit it, or infer its coding from a desired numerical result.', ['S1.posteam_score','S1.defteam_score','S1.score_differential','S1.posteam','S1.defteam','S1.season','S2.div_game'],9,'Performance; Control Variables','inferred')
step('The publication does not state a missing-data rule. Proposed origin: use a common complete-case set on the union of M1–M3 variables after sample and classification rules are settled, record exclusions, and use no imputation or weights. Report any groups lost through conditional likelihood or separation. This is an implementation assumption requiring freezing before fitting, not a documented exclusion.', ['risk_taking','total_points','yards_first_down','yards_touchdown','same_division','same_conference','home_field','season_week','minutes_remaining','performance_below','performance_below_sq','performance_above','below_indicator','offense_team','season_effect'],9,'Data Analysis Model; Table 5 on PDF p. 11','unclear')

variables=[]
def var(name,role,definition,cols,coding,p,w,certainty='explicit'):
    variables.append({'name':name,'role':role,'definition':definition,'registry_columns':cols,'coding':coding,'source':src(p,w),'certainty':certainty})
var('risk_taking','dependent','Offensive choice on fourth down: conversion attempt versus punt or field-goal attempt, regardless of success. For unambiguous executed S1 pass/run (including sacks and scrambles) classify as attempt, and for unambiguous punt/field_goal classify as non-attempt. Use description and kick flags to detect conflicts/fakes; unresolved unusual plays remain missing until a coding rule is frozen.','S1.play_type S1.pass_attempt S1.rush_attempt S1.sack S1.punt_attempt S1.field_goal_attempt S1.fourth_down_converted S1.fourth_down_failed S1.desc S1.aborted_play S1.qb_kneel S1.qb_spike'.split(),'1 = conversion attempted; 0 = punt or field goal attempted; missing is not 0',8,'Variables / Risk Taking','inferred')
var('performance_gap','focal','Auxiliary pre-play point gap relative to aspiration: d = posteam_score - (defteam_score + 1) = score_differential - 1. Subtract the aspiration offset once, not twice. Use the worked example in the methods to disambiguate wording. Provider pre-play score columns are preferred over total_home_score/total_away_score, whose timing is disputed in the supplied dictionary.', ['S1.posteam_score','S1.defteam_score','S1.score_differential'],'points; d = 0 means offense leads by one; a tied score gives d = -1',9,'Performance')
var('performance_below','focal','b = min(d,0), with missing d remaining missing; negative distance below the aspiration threshold, zero above.', ['S1.posteam_score','S1.defteam_score','S1.score_differential'],'continuous signed points, no absolute value or standardization',9,'Performance / spline')
var('performance_below_sq','focal','b*b, where b is performance_below; zero above aspiration, missing if b missing.', ['S1.posteam_score','S1.defteam_score','S1.score_differential'],'squared points, not square of the unsplit gap for all observations',9,'Performance / squared term')
