axes=[]
def axis(i,decision,priority,origin,p,w,alternatives,notes='',compatible=None):
    levels=[{'level_id':f'A{i}.0','description':origin,'is_origin':True,'source':src(p,w)}]
    for j,(desc,label,why,pg,loc) in enumerate(alternatives,1):
        levels.append({'level_id':f'A{i}.{j}','description':desc,'is_origin':False,'label':label,'rationale':why,'basis':'article','source':src(pg,loc)})
    axes.append({'axis_id':f'A{i}','decision':decision,'priority_class':priority,'levels':levels,'compatible_with':compatible or ['all'],'notes':notes})
